   643          (*cp >= endp || endp - *cp < itf8_bytes[up[0]>>4])) {
   644          if (err) *err = 1;
   645          return 0;
   646      }
   647
   648      if (up[0] < 0x80) {
   649          (*cp)++;
   650          return up[0];
   651      } else if (up[0] < 0xc0) {
   652          (*cp)+=2;
   653          return ((up[0] <<8) |  up[1])                           & 0x3fff;
   654      } else if (up[0] < 0xe0) {
   655          (*cp)+=3;
