  2407   */
  2408  static BGZF *bgzf_open_ref(char *fn, char *mode, int is_md5) {
  2409      BGZF *fp;
  2410
  2411      if (!is_md5 && !hisremote(fn)) {
  2412          char fai_file[PATH_MAX];
  2413
  2414          snprintf(fai_file, PATH_MAX, "%s.fai", fn);
  2415          if (access(fai_file, R_OK) != 0)
  2416              if (fai_build(fn) != 0)
  2417                  return NULL;
  2418      }
  2419
  2420      if (!(fp = bgzf_open(fn, mode))) {
  2421          perror(fn);
  2422          return NULL;
  2423      }
  2424
  2425      if (fp->is_compressed == 1 && bgzf_index_load(fp, fn, ".gzi") < 0) {
  2426          hts_log_error("Unable to load .gzi index '%s.gzi'", fn);
  2427          bgzf_close(fp);
