  2434  /*
  2435   * Loads a FAI file for a reference.fasta.
  2436   * "is_err" indicates whether failure to load is worthy of emitting an
  2437   * error message. In some cases (eg with embedded references) we
  2438   * speculatively load, just in case, and silently ignore errors.
  2439   *
  2440   * Returns the refs_t struct on success (maybe newly allocated);
  2441   *         NULL on failure
  2442   */
  2443  static refs_t *refs_load_fai(refs_t *r_orig, const char *fn, int is_err) {
  2444      hFILE *fp = NULL;
  2445      char fai_fn[PATH_MAX];
  2446      char line[8192];
  2447      refs_t *r = r_orig;
  2448      size_t fn_l = strlen(fn);
  2449      int id = 0, id_alloc = 0;
  2450
  2451      RP("refs_load_fai %s\n", fn);
  2452
  2453      if (!r)
  2454          if (!(r = refs_create()))
  2455              goto err;
  2456
  2457      if (r->fp)
  2458          if (bgzf_close(r->fp) != 0)
  2459              goto err;
  2460      r->fp = NULL;
  2461
  2462      /* Look for a FASTA##idx##FAI format */
  2463      char *fn_delim = strstr(fn, HTS_IDX_DELIM);
  2464      if (fn_delim) {
  2465          if (!(r->fn = string_ndup(r->pool, fn, fn_delim - fn)))
  2466              goto err;
  2467          fn_delim += strlen(HTS_IDX_DELIM);
  2468          snprintf(fai_fn, PATH_MAX, "%s", fn_delim);
  2469      } else {
  2470          /* An index file was provided, instead of the actual reference file */
  2471          if (fn_l > 4 && strcmp(&fn[fn_l-4], ".fai") == 0) {
  2472              if (!r->fn) {
  2473                  if (!(r->fn = string_ndup(r->pool, fn, fn_l-4)))
  2474                      goto err;
  2475              }
  2476              snprintf(fai_fn, PATH_MAX, "%s", fn);
  2477          } else {
  2478          /* Only the reference file provided. Get the index file name from it */
  2479              if (!(r->fn = string_dup(r->pool, fn)))
  2480                  goto err;
  2481              sprintf(fai_fn, "%.*s.fai", PATH_MAX-5, fn);
  2482          }
  2483      }
  2484
  2485      if (!(r->fp = bgzf_open_ref(r->fn, "r", 0))) {
  2486          hts_log_error("Failed to open reference file '%s'", r->fn);
  2487          goto err;
  2488      }
  2489
  2490      if (!(fp = hopen(fai_fn, "r"))) {
  2491          hts_log_error("Failed to open index file '%s'", fai_fn);
  2492          if (is_err)
  2493              perror(fai_fn);
  2494          goto err;
  2495      }
  2496      while (hgets(line, 8192, fp) != NULL) {
  2497          ref_entry *e = malloc(sizeof(*e));
  2498          char *cp;
  2499          int n;
  2500          khint_t k;
